/**
 * document-pipeline.ts — 企业文档异步 LLM 分析管线
 *
 * P2-19: 三层漏斗——文档发现→信号提取→信号映射。
 * 替代 Phase 1 纯规则文档解析，用 LLM 识别隐含诊断信号。
 *
 * 三层架构：
 *   Layer 1: 文档发现与分类 — 纯规则，< 5 秒，识别文档类型+相关性评分
 *   Layer 2: 信号提取 — 分块(2000字) + 关键词 + LLM 隐含信号识别
 *   Layer 3: 信号映射 — 按六缝隙分类，按诊断模块分发，构建证据链
 *
 * 异步设计：文档分析不阻断主诊断流程。Phase 1 先用已有信号进入 Phase 2，
 * 文档分析结果异步追加到证据池。进度通过 documentQueueStatus 追踪。
 */
import type { DiagnosisEvidence } from './types';
/** 文档诊断价值等级 */
export type DocPriority = 'P0' | 'P1' | 'P2' | 'P3';
/** 识别到的文档类型 */
export type DocType = 'team_charter' | 'postmortem' | 'project_plan' | 'meeting_notes' | 'team_communication' | 'architecture_doc' | 'performance_review' | 'agent_config' | 'unknown';
/** 文档元数据 */
export interface DocumentMeta {
    path: string;
    filename: string;
    docType: DocType;
    priority: DocPriority;
    relevanceScore: number;
    wordCount: number;
    extractedDate?: string;
    extractedAuthor?: string;
    extractedTeam?: string;
}
/** 原始信号碎片 */
export interface RawSignal {
    signalId: string;
    docPath: string;
    chunkIndex: number;
    /** 匹配的原文片段 */
    snippet: string;
    /** 信号关键词 */
    keywords: string[];
    /** 关联的六缝隙维度 */
    gapDimension?: string;
    /** 置信度 */
    confidence: number;
    /** 提取方式 */
    extractionMethod: 'keyword_match' | 'llm_inferred';
    /** LLM 推理（仅 llm_inferred） */
    llmReasoning?: string;
}
/** 文档队列状态 */
export interface DocumentQueueStatus {
    totalDocuments: number;
    processedDocuments: number;
    totalChunks: number;
    processedChunks: number;
    signalsExtracted: number;
    phase: 'discovering' | 'extracting' | 'mapping' | 'complete' | 'error';
    error?: string;
    startedAt: string;
    completedAt?: string;
}
/** 文档分析结果 */
export interface DocumentAnalysisResult {
    meta: DocumentMeta[];
    signals: RawSignal[];
    evidence: DiagnosisEvidence[];
    queueStatus: DocumentQueueStatus;
}
/**
 * Layer 1: 扫描文档列表，识别类型、计算相关性、排序。
 * 输入：文件路径列表 + 可选内容预览（前 500 字）
 * 输出：按诊断价值排序的 DocumentMeta[]
 */
export declare function discoverDocuments(files: Array<{
    path: string;
    preview?: string;
}>): DocumentMeta[];
/**
 * Layer 2: 从文档文本中提取原始信号。
 * 输入：文档文本 + 元数据
 * 输出：RawSignal[]（关键词匹配 + 规则）
 *
 * LLM 推断通过独立函数 refineWithLLM() 调用，不在此函数内。
 */
export declare function extractSignals(doc: DocumentMeta, content: string): RawSignal[];
/**
 * LLM 提炼提示模板：从文档块中识别关键词匹配不到的隐含信号。
 * 对标 Hermes 后台审查模式——独立 LLM 调用，不污染主对话上下文。
 */
export declare function buildLLMRefinePrompt(chunk: string, docType: DocType): string;
/**
 * 解析 LLM 返回的 JSON 信号列表
 */
export declare function parseLLMSignals(llmOutput: string, docPath: string, chunkIndex: number): RawSignal[];
/**
 * Layer 3: 将原始信号映射为 DiagnosisEvidence。
 * 按六缝隙维度分类，去重，构建证据链。
 */
export declare function mapSignalsToEvidence(signals: RawSignal[], teamId: string): DiagnosisEvidence[];
/**
 * 运行完整文档分析管线（Layer 1→2→3）。
 * Layer 2 的 LLM 部分通过可选的 llmRefine 回调异步执行。
 */
export declare function runDocumentPipeline(files: Array<{
    path: string;
    preview?: string;
    content?: string;
}>, teamId: string): DocumentAnalysisResult;
declare let processingStatus: 'idle' | 'processing' | 'complete';
/** 将文档加入异步处理队列 */
export declare function enqueueDocument(path: string, content: string, teamId: string): void;
/** 获取队列状态 */
export declare function getDocumentQueueLength(): number;
/** 获取处理状态 */
export declare function getProcessingStatus(): typeof processingStatus;
/** 清空队列（测试用） */
export declare function clearDocumentQueue(): void;
export {};
